// Опенинг в каждом аниме в своём месте, поэтому пропуск — по нажатию из нижнего ряда.
 void skipIntro(){seekTo((pendingSeek>=0?pendingSeek:player.getTime())+SKIP_STEP);status.setText("Опенинг пропущен");}
 void speeds(){String[] names=new String[RATES.length];int current=1;for(int i=0;i<RATES.length;i++){names[i]=rateText(RATES[i]);if(Math.abs(RATES[i]-rate)<0.01f)current=i;}new AlertDialog.Builder(this).setTitle("Скорость").setSingleChoiceItems(names,current,(d,i)->{rate=RATES[i];player.setRate(rate);speedButton.setText("Скорость "+rateText(rate));d.dismiss();}).setNegativeButton("Закрыть",null).show();}
