 void togglePlayback(){if(player==null)return;if(player.isPlaying()){player.pause();panel.setVisibility(View.VISIBLE);seek.requestFocus();}else resume();}
 // После паузы аудиовывод Android на приставке перезапускается и звук уходит от картинки.
 // Точная перемотка на текущее место заново выравнивает звук по видео; до первого кадра звук приглушён.
